import { ChefHat} from "lucide-react";

function Header() {
  return (
    <header className="bg-white/80 backdrop-blur border-b">
      <div className="flex flex-row max-w-7xl mx-auto px-6 h-20  ">

        {/* Left div */}
        <div className="">
          <ChefHat/>
        </div>

        {/* Center div */}
        <div className="mx-auto">
          <h1 className="text-2xl font-semibold">ChefGPT</h1>
        </div>

        {/* Right div */}
        <div className="">
          <ChefHat/>
        </div>

      </div>
    </header>
  );
}

export default Header;
